// Monta vídeo final: intro + slides + outro
// Input:
// {
//   production_id: string
//   intro_url: string        (URL pública ou MinIO presigned)
//   slide_urls: string[]    (em ordem)
//   outro_url: string
// }

const MONTAGEM = $env.MONTAGEM_URL || 'http://montagem:3000';

const body = $input.first().json.body || $input.first().json;
const pid  = body.production_id;

const clips = [
  body.intro_url,
  ...(body.slide_urls || []),
  body.outro_url,
].filter(Boolean);

if (clips.length < 2) throw new Error('Mínimo 2 clips para montar');

console.log(`[${pid}] Montando ${clips.length} clips...`);

const r = await fetch(`${MONTAGEM}/concat`, {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({
    production_id: pid,
    clips,
    output_bucket: 'cirlene-video',
    output_key: `${pid}/final.mp4`,
  }),
});

if (!r.ok) {
  const err = await r.text();
  throw new Error(`Montagem falhou: ${r.status} ${err}`);
}

const result = await r.json();
console.log(`[${pid}] Final: ${result.path}`);

return [{
  json: {
    production_id: pid,
    final_path: result.path,
    final_url:  result.url,
    clip_count: clips.length,
  }
}];
